const data = $input.first().json;
const today = new Date();
const end   = today.toISOString().split('T')[0];
const start = new Date(today.getTime() - 28 * 86400000).toISOString().split('T')[0];

// Construire la map URL → pageId depuis les résultats Notion
const notionMap = {};
for (const page of (data.results || [])) {
  const url = page.properties?.URL?.url || '';
  if (url && url.startsWith('http')) {
    notionMap[url] = page.id;
  }
}

const count = Object.keys(notionMap).length;
if (count === 0) throw new Error('Aucun article avec URL dans Notion. Vérifier la colonne "URL".');

// Construire la requête GSC
const siteUrl    = 'https://schoolswp.com/';
const encodedUrl = encodeURIComponent(siteUrl);
const gscUrl  = `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodedUrl}/searchAnalytics/query`;
const gscBody = { startDate: start, endDate: end, dimensions: ['page'], rowLimit: 25000, startRow: 0 };

return [{ json: { notionMap, notionCount: count, gscUrl, gscBody, endDate: end } }];

const gscRaw   = $input.first().json;
const prev     = $('Code - Extract Notion + Build GSC Query').first().json;
const notionMap = prev.notionMap;
const endDate   = prev.endDate;

// Construire la map GSC : URL → métriques
const gscMap = {};
for (const row of (gscRaw.rows || [])) {
  const url = row.keys && row.keys[0];
  if (url) {
    gscMap[url] = {
      clics:       Math.round(row.clicks      || 0),
      impressions: Math.round(row.impressions || 0),
      ctr:         Math.round((row.ctr        || 0) * 10000) / 10000,
      position:    Math.round((row.position   || 0) * 10) / 10
    };
  }
}

// Joindre : garder uniquement les articles présents dans GSC ET dans Notion
const updates = [];
for (const [url, pageId] of Object.entries(notionMap)) {
  const gsc = gscMap[url];
  if (!gsc) continue;
  updates.push({
    pageId,
    url,
    clics:       gsc.clics,
    impressions: gsc.impressions,
    ctr:         gsc.ctr,
    position:    gsc.position,
    endDate
  });
}

if (updates.length === 0) {
  throw new Error(`Aucune correspondance URL entre Notion (${Object.keys(notionMap).length}) et GSC (${Object.keys(gscMap).length}). Vérifier les URLs dans Notion.`);
}

return updates.map(u => ({ json: u }));

const results = $input.all();
const success = results.filter(r => !r.json.object?.includes('error')).length;
const prev    = $('Code - Join GSC + Notion').all();
const total   = prev.length;
const week    = prev[0]?.json.endDate || new Date().toISOString().split('T')[0];

return [{ json: {
  status:  'done',
  week,
  updated: success,
  total,
  message: `GSC → Notion sync ${week} : ${success}/${total} articles mis à jour`
} }];
